1	/**
2	 * BestiaryApi.ts
3	 *
4	 * High-fidelity interface for the Official RuneScape Bestiary.
5	 * Provides authoritative monster statistics, weaknesses, and spawn data.
6	 *
7	 * Endpoint: http://services.runescape.com/m=itemdb_rs/bestiary
8	 */
9	
10	import { ApiThrottle } from './ApiThrottle.js';
11	import { createLogger } from './logger.js';
12	
13	const logger = createLogger('BestiaryApi');
14	const BESTIARY_BASE = 'http://services.runescape.com/m=itemdb_rs/bestiary';
15	
16	export interface BestiaryBeastData {
17	    id: number;
18	    name: string;
19	    examine: string;
20	    combatLevel: number;
21	    lifepoints: number;
22	    attack: number;
23	    defence: number;
24	    magic: number;
25	    ranged: number;
26	    weakness: string;
27	    slayerLevel: number;
28	    slayerCategory: string;
29	    size: number;
30	    aggressive: boolean;
31	    poisonous: boolean;
32	    areas: string[];
33	    animations: Record<string, any>;
34	    members: boolean;
35	    xp: number;
36	}
37	
38	export interface BestiarySearchEntry {
39	    value: number; // The beast ID
40	    label: string; // The beast name (often includes level in parens)
41	}
42	
43	export class BestiaryApi {
44	    private static throttle = ApiThrottle.getInstance();
45	    private static weaknessMap: Record<string, number> | null = null;
46	
47	    /**
48	     * Fetches the canonical mapping of weakness names to IDs.
49	     * Cached for the duration of the session.
50	     */
51	    public static async fetchWeaknessNames(): Promise<Record<string, number>> {
52	        if (this.weaknessMap) return this.weaknessMap;
53	
54	        await this.throttle.acquire('bestiary');
55	        try {
56	            const res = await fetch(`${BESTIARY_BASE}/weaknessNames.json`, {
57	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
58	                signal: AbortSignal.timeout(10000)
59	            });
60	            if (!res.ok) throw new Error(`Weakness fetch failed: ${res.status}`);
61	            this.weaknessMap = await res.json() as Record<string, number>;
62	            return this.weaknessMap;
63	        } catch (err) {
64	            logger.error({ err }, 'Failed to fetch weakness names.');
65	            return {};
66	        }
67	    }
68	
69	    /**
70	     * Search for beasts by name/term.
71	     * @param term Search term (e.g., "Cow"). Supports multiple terms separated by '+'.
72	     */
73	    public static async searchBeasts(term: string): Promise<BestiarySearchEntry[]> {
74	        await this.throttle.acquire('bestiary');
75	        try {
76	            const url = `${BESTIARY_BASE}/beastSearch.json?term=${encodeURIComponent(term)}`;
77	            const res = await fetch(url, {
78	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
79	                signal: AbortSignal.timeout(10000)
80	            });
81	            if (!res.ok) return [];
82	            return await res.json() as BestiarySearchEntry[];
83	        } catch (err) {
84	            logger.error({ term, err }, 'Beast search failed.');
85	            return [];
86	        }
87	    }
88	
89	    /**
90	     * Fetch authoritative beast data by official ID.
91	     * @param beastId The canonical RS3 Beast ID.
92	     */
93	    public static async getBeastData(beastId: number): Promise<BestiaryBeastData | null> {
94	        await this.throttle.acquire('bestiary');
95	
96	        const url = `${BESTIARY_BASE}/beastData.json?beastid=${beastId}`;
97	        try {
98	            const res = await fetch(url, {
99	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
100	                signal: AbortSignal.timeout(10000)
101	            });
102	
103	            if (!res.ok) {
104	                logger.warn({ beastId, status: res.status }, 'Bestiary API non-OK response.');
105	                return null;
106	            }
107	
108	            const data = await res.json() as any;
109	            if (!data) return null;
110	
111	            return {
112	                id: data.id,
113	                name: data.name,
114	                examine: data.description,
115	                combatLevel: data.level,
116	                lifepoints: data.lifepoints,
117	                attack: data.attack,
118	                defence: data.defence,
119	                magic: data.magic,
120	                ranged: data.ranged,
121	                weakness: data.weakness,
122	                slayerLevel: data.slayerlevel,
123	                slayerCategory: data.slayercat,
124	                size: data.size,
125	                aggressive: data.aggressive,
126	                poisonous: data.poisonous,
127	                areas: Array.isArray(data.areas) ? data.areas : [],
128	                animations: data.animations || {},
129	                members: data.members === 'true' || data.members === true,
130	                xp: parseFloat(data.xp || '0'),
131	            };
132	        } catch (err) {
133	            logger.error({ beastId, err }, 'Failed to fetch beast data.');
134	            return null;
135	        }
136	    }
137	
138	    /**
139	     * Returns a list of all area names present in the Bestiary.
140	     */
141	    public static async getAreaNames(): Promise<string[]> {
142	        await this.throttle.acquire('bestiary');
143	        try {
144	            const res = await fetch(`${BESTIARY_BASE}/areaNames.json`, {
145	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
146	                signal: AbortSignal.timeout(10000)
147	            });
148	            if (!res.ok) return [];
149	            return await res.json() as string[];
150	        } catch (err) {
151	            logger.error({ err }, 'Failed to fetch area names.');
152	            return [];
153	        }
154	    }
155	
156	    /**
157	     * Returns all beasts found in a specific area.
158	     */
159	    public static async getBeastsInArea(areaName: string): Promise<BestiarySearchEntry[]> {
160	        await this.throttle.acquire('bestiary');
161	        try {
162	            const url = `${BESTIARY_BASE}/areaBeasts.json?identifier=${encodeURIComponent(areaName)}`;
163	            const res = await fetch(url, {
164	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
165	                signal: AbortSignal.timeout(10000)
166	            });
167	            if (!res.ok) return [];
168	            return await res.json() as BestiarySearchEntry[];
169	        } catch (err) {
170	            logger.error({ areaName, err }, 'Failed to fetch beasts in area.');
171	            return [];
172	        }
173	    }
174	
175	    /**
176	     * Returns a mapping of Slayer category names to their IDs.
177	     */
178	    public static async getSlayerCategories(): Promise<Record<string, number>> {
179	        await this.throttle.acquire('bestiary');
180	        try {
181	            const res = await fetch(`${BESTIARY_BASE}/slayerCatNames.json`, {
182	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
183	                signal: AbortSignal.timeout(10000)
184	            });
185	            if (!res.ok) return {};
186	            return await res.json() as Record<string, number>;
187	        } catch (err) {
188	            logger.error({ err }, 'Failed to fetch slayer categories.');
189	            return {};
190	        }
191	    }
192	
193	    /**
194	     * Returns monsters within a specific slayer category.
195	     */
196	    public static async getBeastsInSlayerCategory(catId: number): Promise<BestiarySearchEntry[]> {
