/**
 * GeApi.ts
 *
 * High-fidelity interface for the RuneScape Wiki Grand Exchange API.
 * Provides real-time prices and historical trends.
 *
 * This API is CORS-friendly and requires a descriptive User-Agent.
 * Endpoint: https://prices.runescape.wiki/api/v1/rs
 */

import { ApiThrottle } from './ApiThrottle.js';
import { createLogger } from './logger.js';

const logger = createLogger('GeApi');
const GE_BASE = 'https://prices.runescape.wiki/api/v1/rs';
const USER_AGENT = 'POG2-Sovereign/1.0 (GE Intelligence Engine; RS3 price enrichment; admin@pog2.internal; +https://github.com/Kbro1989/POG2)';

export interface GeItemDetails {
    id: number;
    name: string;
    current: {
        high: number;
        low: number;
        timestamp: number;
    };
    trends: {
        day: { change: number; trend: string };
        week: { change: number; trend: string };
        month: { change: number; trend: string };
    };
}

export class GeApi {
    private static throttle = ApiThrottle.getInstance();

    /**
     * Fetch real-time item details by official game ID.
     * @param itemId The canonical RS3 Item ID.
     */
    public static async getItemDetails(itemId: number): Promise<GeItemDetails | null> {
        await this.throttle.acquire('ge');

        const url = `${GE_BASE}/latest?id=${itemId}`;
        try {
            const res = await fetch(url, {
                headers: { 'User-Agent': USER_AGENT },
                signal: AbortSignal.timeout(10000)
            });

            if (!res.ok) {
                logger.warn({ itemId, status: res.status }, 'GE API non-OK response.');
                return null;
            }

            const data = await res.json() as any;
            if (!data || !data.data) return null;

            // The API returns an array of results for the query
            const itemData = data.data.find((i: any) => i.id === itemId);
            if (!itemData) return null;

            return {
                id: itemData.id,
                name: itemData.name || 'Unknown',
                current: {
                    high: itemData.high,
                    low: itemData.low,
                    timestamp: itemData.timestamp
                },
                trends: {
                    day: { change: 0, trend: 'stable' }, // Derived from history if needed
                    week: { change: 0, trend: 'stable' },
                    month: { change: 0, trend: 'stable' },
                }
            };
        } catch (err) {
            logger.error({ itemId, err }, 'Failed to fetch GE item details.');
            return null;
        }
    }

    /**
     * Fetch historical price graph for specific item.
     * Returns a sorted array of price values.
     */
    public static async getPriceGraph(itemId: number): Promise<number[]> {
        await this.throttle.acquire('ge');

        const url = `${GE_BASE}/history?id=${itemId}`;
        try {
            const res = await fetch(url, {
                headers: { 'User-Agent': USER_AGENT },
                signal: AbortSignal.timeout(10000)
            });

            if (!res.ok) return [];

            const data = await res.json() as any;
            if (!data || !data.data) return [];

            // The history API returns a series of data points
            const itemHistory = data.data.find((i: any) => i.id === itemId);
            if (!itemHistory || !itemHistory.prices) return [];

            return itemHistory.prices.map((p: any) => p.price);
        } catch (err) {
            logger.error({ itemId, err }, 'Failed to fetch GE price graph.');
            return [];
        }
    }

    /**
     * Simple price parsing for legacy string-based formats.
     * Now largely obsolete as Wiki API provides raw integers.
     */
    public static parseGePrice(priceStr: string): number {
        if (!priceStr) return 0;
        const clean = priceStr.toLowerCase().trim();
        if (clean.endsWith('m')) return Math.floor(parseFloat(clean.replace('m', '')) * 1000000);
        if (clean.endsWith('k')) return Math.floor(parseFloat(clean.replace('k', '')) * 1000);
        const val = parseInt(clean.replace(/,/g, ''), 10);
        return isNaN(val) ? 0 : val;
    }
}

