681	    /**
682	     * Detect references to sub-drop-tables in the wikitext.
683	     */
684	    private detectSubTableRefs(wikitext: string): string[] {
685	        const found: string[] = [];
686	        const lowerText = wikitext.toLowerCase();
687	
688	        for (const table of WikiEquipmentEnricher.KNOWN_SUB_TABLES) {
689	            if (lowerText.includes(`{{${table.toLowerCase()}`)) {
