904	     * Batch enrichment with progress callback.
905	     * Respectfully rate-limited — each API hit spaced by RATE_LIMIT_MS.
906	     */
907	    public async batchEnrich(
908	        names: string[],
909	        type: 'item' | 'monster',
910	        onProgress?: (current: number, total: number, name: string) => void
911	    ): Promise<Map<string, WikiPageData>> {
912	        const results = new Map<string, WikiPageData>();
913	
914	        logger.info({ count: names.length, type }, 'Beginning batch wiki enrichment...');
915	
916	        for (let i = 0; i < names.length; i++) {
917	            const name = names[i];
918	            onProgress?.(i + 1, names.length, name);
919	
920	            try {
921	                const data = type === 'item'
922	                    ? await this.enrichItem(name)
923	                    : await this.enrichMonster(name);
924	                results.set(name, data);
925	            } catch (err) {
926	                logger.warn({ name, err }, 'Batch enrichment failed for entry.');
927	            }
928	        }
929	
930	        logger.info({ completed: results.size, total: names.length }, 'Batch enrichment complete.');
931	        return results;
