985	        const updates: WikiUpdateMeta[] = [];
986	        // This is a simplified parser for the Updates page structure
987	        const updateBlocks = wikitext.split('==');
988	
989	        for (const block of updateBlocks) {
990	            const dateMatch = block.match(/(\d{1,2}\s\w+ \d{4})/);
991	            if (!dateMatch) continue;
992	
993	            const date = dateMatch[1];
994	            const titleMatch = block.match(/==\s*([^|]+?)\s*\|/);
995	            const title = titleMatch ? titleMatch[1].trim() : 'Unknown Update';
996	
997	            updates.push({
998	                title,
999	                date,
1000	                category: 'General',
1001	                url: `https://runescape.wiki/w/Updates#${encodeURIComponent(title)}`,
1002	                isHotfix: block.toLowerCase().includes('hotfix'),
1003	                isColdfix: false,
1004	                affectedEntities: [] // Would require further parsing of the block text for IDs
1005	            });
1006	        }
1007	
1008	        return updates;
