1	/**
2	 * WikiEquipmentEnricher.ts
3	 *
4	 * Structured parser for RS Wiki Infobox templates and drop tables.
5	 * Extracts equipment bonuses, item metadata, monster stats, and complete
6	 * drop tables (including sub-table resolution) with respectful rate limiting.
7	 *
8	 * Sovereign Substrate: Semantic Enrichment Layer
9	 * Cache Authority: D:\sovereign\atlas\wiki\cache\
10	 *
11	 * Template Coverage:
12	 *   - {{Infobox Bonuses}}  → Equipment combat stats
13	 *   - {{Infobox Item}}     → Item metadata
14	 *   - {{Infobox Monster}}  → Monster/NPC stats
15	 *   - {{DropsLine}}        → Individual drop entries
16	 *   - {{Rare drop table}}, {{Gem drop table}}, etc. → Sub-table resolution
17	 */
18	
19	import { createLogger } from './logger.js';
20	import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
21	import { join } from 'path';
22	import { QueryClassifier, QueryType } from './QueryClassifier.js';
23	import { CacheForensicsLimb } from '../limbs/spatial/CacheForensicsLimb.js';
24	import { GeApi, GePrice } from './GeApi.js';
25	import { BestiaryApi, BestiaryBeastData } from './BestiaryApi.js';
26	
27	const logger = createLogger('WikiEquipmentEnricher');
28	
29	// ═══════════════════════════════════════════════════════
30	// Interfaces
31	// ═══════════════════════════════════════════════════════
32	
33	export interface WikiEquipmentBonuses {
34	    tier: number;
35	    slot: string;          // mainhand, off-hand, 2h, head, body, legs, feet, hands, back, neck, ring, ammo, pocket, shield
36	    class: string;         // melee, ranged, magic, necromancy, all, hybrid
37	    style: string;         // slash, stab, crush, none
38	    damage: number;
39	    accuracy: number;
40	    armour: number;
41	    lifeBonus: number;
42	    prayerBonus: number;
43	    attackSpeed: string;   // fastest, fast, average, slow, slowest
44	}
45	
46	export interface WikiItemMeta {
47	    name: string;
48	    examine: string;
49	    tradeable: boolean;
50	    stackable: boolean;
51	    members: boolean;
52	    weight: number;
53	    highAlch: number;
54	    lowAlch: number;
55	    /** Grand Exchange price in coins. 0 = not on GE or unknown. */
56	    geValue: number;
57	    _geSource?: string;
58	    _geTimestamp?: number;
59	    quest: string;
60	    release: string;
61	}
62	
63	export interface WikiMonsterMeta {
64	    name: string;
65	    combatLevel: number;
66	    lifePoints: number;
67	    maxHit: number;
68	    weakness: string;
69	    slayerLevel: number;
70	    slayerCategory: string;
71	    aggressive: boolean;
72	    poisonous: boolean;
73	    attackStyle: string;
74	    members: boolean;
75	    experience: number;
76	    
77	    // March 2026 Combat Affinities
78	    defence: number;
79	    armour: number;
80	    affinityMelee: number;
81	    affinityRanged: number;
82	    affinityMagic: number;
83	    affinityNecromancy: number;
84	}
85	
86	export interface WikiDropEntry {
87	    itemName: string;
88	    quantity: string;       // "1", "1-3", "1 (noted)", etc.
89	    rarity: string;         // "Always", "Common", "Uncommon", "Rare", "Very rare", "1/128"
90	    isMembers: boolean;
91	    notes: string;
92	    /** Grand Exchange value in coins. 0 = not tradeable or unknown. Used by LootBeamRegistry. */
93	    geValue: number;
94	}
95	
96	export interface WikiDropTable {
97	    section: string;        // "Main", "Charms", "Tertiary", sub-table name
98	    entries: WikiDropEntry[];
99	}
100	
101	export interface WikiPageData {
102	    title: string;
103	    fetchedAt: number;
104	    bonuses: WikiEquipmentBonuses | null;
105	    itemMeta: WikiItemMeta | null;
106	    monsterMeta: WikiMonsterMeta | null;
107	    dropTables: WikiDropTable[];
108	    rawVariables: Record<string, string>;
109	    pageType?: 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore';
110	    extract?: string;
111	    categoryMembers?: string[];
112	}
113	
114	export interface WikiUpdateMeta {
115	    title: string;
116	    date: string;
117	    category: string;
118	    url: string;
119	    isHotfix: boolean;
120	    isColdfix: boolean;
121	    affectedEntities: number[];
122	}
123	
124	// ═══════════════════════════════════════════════════════
125	// Generic Enrichment Types
126	// ═══════════════════════════════════════════════════════
127	
128	export interface WikiGenericMeta {
129	    title: string;
130	    pageType: 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore';
131	    extract: string;
132	    infoboxVars: Record<string, string>;
133	    categoryMembers?: string[];
134	    fetchedAt: number;
135	}
136	
137	export class WikiEquipmentEnricher {
138	    private static instance: WikiEquipmentEnricher;
139	
140	    private readonly API_BASE = 'https://runescape.wiki/api.php';
141	    private readonly USER_AGENT = 'POG2-Sovereign/1.0 (Sovereign Research Node; admin@pog2.internal; respectful-soft-parse; +https://github.com/Kbro1989/POG2)';
142	    private readonly RATE_LIMIT_MS = 1500;
143	    private readonly CACHE_DIR: string;
144	    private readonly CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
145	
146	    private lastRequestTime = 0;
147	    private requestCount = 0;
148	
149	    private constructor() {
150	        this.CACHE_DIR = join('D:', 'sovereign', 'atlas', 'wiki', 'cache');
151	        this.ensureCacheDir();
152	    }
