286	        await this.throttle();
287	
288	        const params = new URLSearchParams({
289	            action: 'query',
290	            format: 'json',
291	            list: 'search',
292	            srsearch: query,
293	            srlimit: '1',
294	            origin: '*'
295	        });
296	
297	        try {
298	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
299	                headers: { 'User-Agent': this.USER_AGENT },
300	                signal: AbortSignal.timeout(10000)
301	            });
302	
303	            if (!response.ok) {
304	                if (response.status === 429) {
305	                    const retryAfter = response.headers.get('Retry-After');
306	                    if (retryAfter) {
307	                        ApiThrottle.getInstance().reportRetryAfter('wiki', parseInt(retryAfter, 10));
308	                    }
309	                }
310	                logger.warn({ query, status: response.status }, 'Wiki search non-OK response.');
311	                return null;
