322	    /**
323	     * Resolves a name to wikitext. Tries direct fetch, follows redirects, falls back to search.
324	     */
325	    private async getWikitextForName(name: string): Promise<string | null> {
326	        // Try direct page first
327	        let wikitext = await this.fetchWikitext(name);
328	
329	        // Follow #REDIRECT if the page is a redirect stub
330	        if (wikitext && wikitext.trim().startsWith('#REDIRECT')) {
331	            const redirectMatch = wikitext.match(/\[\[([^\]]+)\]\]/);
332	            if (redirectMatch) {
333	                const redirectTarget = redirectMatch[1].trim();
334	                logger.info({ from: name, to: redirectTarget }, 'Following wiki redirect...');
335	                wikitext = await this.fetchWikitext(redirectTarget);
336	            }
337	        }
338	
339	        if (!wikitext) {
340	            // Fallback: search for the page
341	            const title = await this.searchPage(name);
342	            if (title && title !== name) {
343	                wikitext = await this.fetchWikitext(title);
344	                // Follow redirect on search result too
345	                if (wikitext && wikitext.trim().startsWith('#REDIRECT')) {
346	                    const redirectMatch = wikitext.match(/\[\[([^\]]+)\]\]/);
347	                    if (redirectMatch) {
348	                        const redirectTarget = redirectMatch[1].trim();
349	                        logger.info({ from: title, to: redirectTarget }, 'Following wiki redirect (search fallback)...');
350	                        wikitext = await this.fetchWikitext(redirectTarget);
351	                    }
352	                }
353	            }
354	        }
355	
356	        return wikitext;
357	    }
