359	    // ── Template Parser ────────────────────────────────────
360	
361	    /**
362	     * Extract a single template's parameters from wikitext.
363	     * Handles nested templates via bracket-depth tracking.
364	     */
365	    private extractTemplate(wikitext: string, templateName: string): Record<string, string> | null {
366	        const lowerText = wikitext.toLowerCase();
367	        const lowerName = templateName.toLowerCase();
368	
369	        let searchIdx = 0;
370	        let startIdx = -1;
371	
372	        while (searchIdx < lowerText.length) {
373	            const bracePos = lowerText.indexOf('{{', searchIdx);
374	            if (bracePos === -1) break;
375	
376	            let nameStart = bracePos + 2;
377	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
378	
379	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
380	                const afterName = lowerText[nameStart + lowerName.length];
381	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n' || afterName === '\r' || afterName === undefined) {
382	                    startIdx = bracePos;
383	                    break;
384	                }
385	            }
386	            searchIdx = bracePos + 2;
387	        }
388	
389	        if (startIdx === -1) return null;
390	
391	        // Find matching closing }} using bracket depth
392	        let depth = 0;
393	        let endIdx = startIdx;
394	        for (let i = startIdx; i < wikitext.length - 1; i++) {
395	            if (wikitext[i] === '{' && wikitext[i + 1] === '{') {
396	                depth++;
397	                i++;
398	            } else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
399	                depth--;
400	                i++;
401	                if (depth === 0) {
402	                    endIdx = i + 1;
403	                    break;
404	                }
405	            }
406	        }
407	
408	        if (depth !== 0) return null;
409	
410	        const fullContent = wikitext.substring(startIdx + 2, endIdx - 2);
411	        const pipeIdx = fullContent.indexOf('|');
412	        if (pipeIdx === -1) return {};
413	
414	        return this.parseTemplateParams(fullContent.substring(pipeIdx + 1));
415	    }
416	
417	    /**
418	     * Extract ALL instances of a template from wikitext.
419	     * Critical for DropsLine parsing where each drop is a separate template call.
420	     */
421	    private extractAllTemplateInstances(wikitext: string, templateName: string): Record<string, string>[] {
422	        const results: Record<string, string>[] = [];
423	        const lowerText = wikitext.toLowerCase();
424	        const lowerName = templateName.toLowerCase();
425	        let searchIdx = 0;
426	
427	        while (searchIdx < lowerText.length) {
428	            const bracePos = lowerText.indexOf('{{', searchIdx);
429	            if (bracePos === -1) break;
430	
431	            let nameStart = bracePos + 2;
432	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
433	
434	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
435	                const afterName = lowerText[nameStart + lowerName.length];
436	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n') {
437	                    // Find closing braces
438	                    let depth = 0;
439	                    let endIdx = bracePos;
440	                    for (let i = bracePos; i < wikitext.length - 1; i++) {
441	                        if (wikitext[i] === '{' && wikitext[i + 1] === '{') { depth++; i++; }
442	                        else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
443	                            depth--; i++;
444	                            if (depth === 0) { endIdx = i + 1; break; }
445	                        }
446	                    }
447	
448	                    const fullContent = wikitext.substring(bracePos + 2, endIdx - 2);
449	                    const pipeIdx = fullContent.indexOf('|');
450	                    if (pipeIdx !== -1) {
451	                        results.push(this.parseTemplateParams(fullContent.substring(pipeIdx + 1)));
452	                    }
453	
454	                    searchIdx = endIdx;
455	                    continue;
456	                }
457	            }
458	            searchIdx = bracePos + 2;
459	        }
460	
461	        return results;
462	    }
463	
464	    /**
465	     * Parse pipe-separated template parameters, respecting nested template depth.
466	     * Handles {{nested|templates}} and [[wiki|links]] inside parameter values.
467	     */
468	    private parseTemplateParams(text: string): Record<string, string> {
469	        const params: Record<string, string> = {};
470	        let depth = 0;
471	        let currentParam = '';
472	        let positionalIdx = 1;
473	
474	        for (let i = 0; i < text.length; i++) {
475	            const ch = text[i];
476	            const next = text[i + 1];
477	
478	            if (ch === '{' && next === '{') { depth++; currentParam += '{{'; i++; }
479	            else if (ch === '}' && next === '}') { depth--; currentParam += '}}'; i++; }
480	            else if (ch === '[' && next === '[') { depth++; currentParam += '[['; i++; }
481	            else if (ch === ']' && next === ']') { depth--; currentParam += ']]'; i++; }
482	            else if (ch === '|' && depth === 0) {
483	                this.assignParam(params, currentParam, positionalIdx);
484	                positionalIdx++;
485	                currentParam = '';
486	            } else {
487	                currentParam += ch;
488	            }
489	        }
490	
491	        // Last parameter
492	        if (currentParam.trim()) {
493	            this.assignParam(params, currentParam, positionalIdx);
494	        }
495	
496	        return params;
497	    }
498	
499	    private assignParam(params: Record<string, string>, raw: string, positionalIdx: number): void {
500	        const eqIdx = raw.indexOf('=');
501	        if (eqIdx > 0 && !raw.substring(0, eqIdx).includes('{{')) {
502	            const key = raw.substring(0, eqIdx).trim().toLowerCase();
503	            const value = this.cleanWikiMarkup(raw.substring(eqIdx + 1).trim());
504	            if (key) params[key] = value;
505	        } else {
506	            params[`_${positionalIdx}`] = this.cleanWikiMarkup(raw.trim());
507	        }
508	    }
509	
510	    /**
511	     * Strip wiki markup from a value (links, formatting, refs).
512	     */
513	    private cleanWikiMarkup(text: string): string {
514	        return text
515	            .replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1')  // [[Link|Text]] -> Text
516	            .replace(/'''?/g, '')                                // Bold/italic
517	            .replace(/<ref[^>]*>.*?<\/ref>/gs, '')               // References
518	            .replace(/<ref[^/]*\/>/g, '')                        // Self-closing refs
519	            .replace(/<br\s*\/?>/gi, ' ')                        // Line breaks
520	            .replace(/<!--.*?-->/gs, '')                         // HTML comments
521	            .replace(/&nbsp;/g, ' ')                             // Non-breaking spaces
522	            .trim();
523	    }
