625	    public async parseDropTables(npcName: string): Promise<WikiDropTable[]> {
626	        const wikitext = await this.getWikitextForName(npcName);
627	        if (!wikitext) return [];
628	
629	        const tables: WikiDropTable[] = [];
630	
631	        // Extract all DropsLine instances from the page
632	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
633	
634	        if (dropLines.length > 0) {
635	            const mainEntries: WikiDropEntry[] = dropLines.map(dl => ({
636	                itemName: dl['name'] || dl['_1'] || 'Unknown',
637	                quantity: dl['quantity'] || dl['_2'] || '1',
638	                rarity: dl['rarity'] || dl['_3'] || 'Unknown',
639	                isMembers: this.safeBool(dl['members']),
640	                notes: dl['raritynotes'] || dl['altrarity'] || '',
641	                // ge: Some DropsLine templates include a |ge= param for price override
642	                geValue: this.safeInt(dl['ge'] || dl['value'] || dl['price'] || '0')
643	            }));
644	
645	            tables.push({
646	                section: 'Main',
647	                entries: mainEntries
648	            });
649	        }
650	
651	        // Detect and resolve sub-table references
652	        const subTableRefs = this.detectSubTableRefs(wikitext);
653	        for (const ref of subTableRefs) {
654	            logger.info({ ref, npc: npcName }, 'Resolving sub-table reference...');
655	            const subEntries = await this.resolveSubTable(ref);
656	            if (subEntries.length > 0) {
657	                tables.push({
658	                    section: ref,
659	                    entries: subEntries
660	                });
661	            }
662	        }
663	
664	        return tables;
665	    }
