668	
669	    /** Known sub-drop-table templates on RS Wiki. */
670	    private static readonly KNOWN_SUB_TABLES = [
671	        'Rare drop table',
672	        'Gem drop table',
673	        'Herb drop table',
674	        'Seed drop table',
675	        'Salvage drop table',
676	        'Triskelion drop table',
677	        'Ushabti drop table',
678	        'Shard drop table',
679	        'Spirit gem drop table',
680	        'Uncommon drop table',
681	        'Common drop table',
682	        'Charm drop table'
683	    ];
684	
685	    /**
686	     * Detect references to sub-drop-tables in the wikitext.
687	     */
688	    private detectSubTableRefs(wikitext: string): string[] {
689	        const found: string[] = [];
690	        const lowerText = wikitext.toLowerCase();
691	
692	        for (const table of WikiEquipmentEnricher.KNOWN_SUB_TABLES) {
693	            if (lowerText.includes(`{{${table.toLowerCase()}`)) {
694	                found.push(table);
695	            }
696	        }
697	
698	        return found;
699	    }
