701	    /**
702	     * Fetch and parse a sub-drop-table template page.
703	     * These live at Template:{name} on the wiki.
704	     */
705	    private async resolveSubTable(templateName: string): Promise<WikiDropEntry[]> {
706	        // Check cache
707	        const cached = this.readCache('templates', templateName);
708	        if (cached?.entries) {
709	            logger.debug({ templateName }, 'Sub-table served from cache.');
710	            return cached.entries;
711	        }
712	
713	        // Fetch the template page
714	        const wikitext = await this.fetchWikitext(`Template:${templateName}`);
715	        if (!wikitext) return [];
716	
717	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
718	        const entries: WikiDropEntry[] = dropLines.map(dl => ({
719	            itemName: dl['name'] || dl['_1'] || 'Unknown',
720	            quantity: dl['quantity'] || dl['_2'] || '1',
721	            rarity: dl['rarity'] || dl['_3'] || 'Unknown',
722	            isMembers: this.safeBool(dl['members']),
723	            notes: `[${templateName}] ${dl['raritynotes'] || ''}`.trim(),
724	            // Sub-tables (RDT, Gem table) typically have no direct GE price in the template.
725	            // geValue defaults to 0; LootBeamRegistry will use the rarity label (e.g. "Rare drop table") instead.
726	            geValue: this.safeInt(dl['ge'] || dl['value'] || '0')
727	        }));
728	
729	        // Cache the resolved sub-table
730	        this.writeCache('templates', templateName, { entries });
731	        logger.info({ templateName, count: entries.length }, 'Sub-table resolved and cached.');
732	
733	        return entries;
734	    }
