736	    // ── Generic Enrichment Logic ─────────────────────────────
737	
738	    private detectPageType(wikitext: string): 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore' {
739	        const lower = wikitext.toLowerCase();
740	        if (lower.includes('{{infobox monster')) return 'npc';
741	        if (lower.includes('{{infobox item')) return 'item';
742	        if (lower.includes('{{infobox bonuses')) return 'equipment';
743	        if (lower.includes('{{infobox location') || lower.includes('{{infobox area'))) return 'place';
744	        if (lower.includes('{{infobox mechanic') || lower.includes('{{infobox gameplay'))) return 'mechanic';
745	        return 'lore';
746	    }
