760	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
761	                headers: { 'User-Agent': this.USER_AGENT },
762	                signal: AbortSignal.timeout(10000)
763	            });
764	            const data = await response.json() as any;
