910	     */
911	    public async batchEnrich(
912	        names: string[],
913	        type: 'item' | 'monster',
914	        onProgress?: (current: number, total: number, name: string) => void
915	    ): Promise<Map<string, WikiPageData>> {
916	        const results = new Map<string, WikiPageData>();
917	
918	        logger.info({ count: names.length, type }, 'Beginning batch wiki enrichment...');
919	
920	        for (let i = 0; i < names.length; i++) {
921	            const name = names[i];
922	            onProgress?.(i + 1, names.length, name);
923	
924	            try {
925	                const data = type === 'item'
926	                    ? await this.enrichItem(name)
927	                    : await this.enrichMonster(name);
928	                results.set(name, data);
929	            } catch (err) {
930	                logger.warn({ name, err }, 'Batch enrichment failed for entry.');
931	            }
932	        }
933	
934	        logger.info({ completed: results.size, total: names.length }, 'Batch enrichment complete.');
935	        return results;
