938	    /**
939	     * Unified entry point for entity resolution.
940	     * Uses QueryClassifier to route requests between Structural (Cache) and Semantic (Wiki) paths.
941	     */
942	    public async enrichEntity(query: string): Promise<any> {
943	        const classified = QueryClassifier.classify(query);
944	        logger.info({ query, type: classified.type }, 'Classifying entity query...');
945	
946	        // 1. Route Structural Queries exclusively to CacheForensicsLimb
947	        if (classified.type.startsWith('structural_')) {
948	            const forensics = CacheForensicsLimb.getInstance();
949	            const id = classified.extractedIds[0];
950	
951	            if (classified.type === 'structural_enum') {
952	                return { type: 'enum', data: await forensics.getEnumDetails(id), tag: '[CACHE_VERIFIED]' };
953	            }
954	            if (classified.type === 'structural_id') {
955	                const item = await forensics.getItemDetails(id);
956	                const npc = await forensics.getNpcDetails(id);
957	                return { type: 'id_resolution', item, npc, tag: '[CACHE_VERIFIED]' };
958	            }
959	            return { type: 'structural', data: `Structural query ${classified.type} handled by CacheForensicsLimb`, tag: '[CACHE_EXCLUSIVE]' };
960	        }
961	
962	        // 2. Route Spatial Queries
963	        if (classified.type.startsWith('spatial_')) {
964	            return { type: 'spatial', query: classified.raw, tag: '[SPATIAL_SENSITIVE]' };
965	        }
966	
967	        // 3. Route Semantic/Hybrid Queries to Wiki + APIs
968	        const name = classified.extractedNames[0] || query;
969	
970	        // Try monster first, then item, then generic
971	        const monster = await this.enrichMonster(name);
972	        if (monster.monsterMeta) return { ...monster, tag: '[VERIFIED]' };
973	
974	        const item = await this.enrichItem(name);
975	        if (item.itemMeta) return { ...item, tag: '[VERIFIED]' };
976	
977	        return { ...await this.enrichGeneric(name), tag: '[WIKI_ONLY]' };
978	    }
