984	    public async fetchLatestUpdates(): Promise<WikiUpdateMeta[]> {
985	        logger.info('Fetching latest game updates for temporal grounding...');
986	        const wikitext = await this.getWikitextForName('Updates');
987	        if (!wikitext) return [];
