995	            if (!dateMatch) continue;
996	
997	            const date = dateMatch[1];
998	            const titleMatch = block.match(/==\s*([^|]+?)\s*\|/);
999	            const title = titleMatch ? titleMatch[1].trim() : 'Unknown Update';
1000	
1001	            updates.push({
1002	                title,
1003	                date,
1004	                category: 'General',
1005	                url: `https://runescape.wiki/w/Updates#${encodeURIComponent(title)}`,
1006	                isHotfix: block.toLowerCase().includes('hotfix'),
1007	                isColdfix: false,
1008	                affectedEntities: [] // Would require further parsing of the block text for IDs
1009	            });
1010	        }
1011	
1012	        return updates;
