1023	
1024	        if (bonuses.tier > 0) {
1025	            const cls = bonuses.class.toLowerCase();
1026	            if (cls === 'melee' || bonuses.style === 'slash' || bonuses.style === 'stab' || bonuses.style === 'crush') {
1027	                patch.req_attack = bonuses.tier;
1028	            } else if (cls === 'ranged') {
1029	                patch.req_ranged = bonuses.tier;
1030	            } else if (cls === 'magic') {
1031	                patch.req_magic = bonuses.tier;
1032	            } else if (cls === 'necromancy') {
1033	                patch.req_necromancy = bonuses.tier;
