417	    /**
418	     * Extract ALL instances of a template from wikitext.
419	     * Critical for DropsLine parsing where each drop is a separate template call.
420	     */
421	    private extractAllTemplateInstances(wikitext: string, templateName: string): Record<string, string>[] {
422	        const results: Record<string, string>[] = [];
423	        const lowerText = wikitext.toLowerCase();
424	        const lowerName = templateName.toLowerCase();
425	        let searchIdx = 0;
426	
427	        while (searchIdx < lowerText.length) {
428	            const bracePos = lowerText.indexOf('{{', searchIdx);
429	            if (bracePos === -1) break;
430	
431	            let nameStart = bracePos + 2;
432	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
433	
434	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
435	                const afterName = lowerText[nameStart + lowerName.length];
436	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n') {
437	                    // Find closing braces
438	                    let depth = 0;
439	                    let endIdx = bracePos;
440	                    for (let i = bracePos; i < wikitext.length - 1; i++) {
441	                        if (wikitext[i] === '{' && wikitext[i + 1] === '{') { depth++; i++; }
442	                        else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
443	                            depth--; i++;
444	                            if (depth === 0) { endIdx = i + 1; break; }
445	                        }
446	                    }
447	
448	                    const fullContent = wikitext.substring(bracePos + 2, endIdx - 2);
449	                    const pipeIdx = fullContent.indexOf('|');
450	                    if (pipeIdx !== -1) {
451	                        results.push(this.parseTemplateParams(fullContent.substring(pipeIdx + 1)));
452	                    }
453	
454	                    searchIdx = endIdx;
455	                    continue;
456	                }
457	            }
458	            searchIdx = bracePos + 2;
459	        }
460	
461	        return results;
462	    }
