        { id: 21, name: 'Farming', maxLevel: 120, f2pMaxLevel: 5, isMembers: true, isElite: false, type: 'Gathering' },
        { id: 22, name: 'Construction', maxLevel: 99, f2pMaxLevel: 5, isMembers: true, isElite: false, type: 'Artisan' },
