        { id: 25, name: 'Dungeoneering', maxLevel: 120, f2pMaxLevel: 120, isMembers: false, isElite: false, type: 'Support' },
        { id: 26, name: 'Divination', maxLevel: 99, f2pMaxLevel: 5, isMembers: true, isElite: false, type: 'Gathering' },
