        { id: 28, name: 'Archaeology', maxLevel: 120, f2pMaxLevel: 20, isMembers: true, isElite: false, type: 'Gathering' },
        { id: 29, name: 'Necromancy', maxLevel: 120, f2pMaxLevel: 20, isMembers: true, isElite: false, type: 'Combat' }
