/**
 * OfficialPlayerDataApi.ts
 *
 * Runemetrics + Hiscores API client for RS3 player data.
 * Routes through Cloudflare Worker CORS proxy.
 * Aligns with Jagex API specification.
 *
 * Sovereign Substrate: Player Data Layer
 * Cache Authority: D:\\sovereign\\atlas\\player\\cache\\
 */

import { createLogger } from './logger.js';
import { ApiThrottle } from './ApiThrottle.js';

const logger = createLogger('OfficialPlayerDataApi');

// ═══════════════════════════════════════════════════════
// Interfaces
// ═══════════════════════════════════════════════════════

export interface PlayerProfile {
  name: string;
  rank: string;
  totalSkill: number;
  totalXp: number;
  combatLevel: number;
  skills: Array<{
    id: number;
    name: string;
    level: number;
    xp: number;
    rank: number;
  }>;
  activities: Array<{
    text: string;
    date: string;
  }>;
  questsStarted: number;
  questsComplete: number;
  questsNotStarted: number;
  loggedIn: boolean;
}

export interface HiscoreEntry {
  rank: number;
  level: number;
  xp: number;
}

export interface MonthlyXpData {
  skillId: number;
  skillName: string;
  averageXpGain: number;
  totalGain: number;
  totalXp: number;
  monthlyData: Array<{
    month: string;
    xp: number;
  }>;
}

export interface QuestData {
  title: string;
  status: 'COMPLETED' | 'STARTED' | 'NOT_STARTED';
  difficulty: number;
  members: boolean;
  questPoints: number;
  userEligible: boolean;
}

// ═══════════════════════════════════════════════════════
// Skill ID Mapping (0-28)
// ═══════════════════════════════════════════════════════

export const SKILL_NAMES: Record<number, string> = {
  0: 'Attack', 1: 'Defence', 2: 'Strength', 3: 'Constitution',
  4: 'Ranged', 5: 'Prayer', 6: 'Magic', 7: 'Cooking',
  8: 'Woodcutting', 9: 'Fletching', 10: 'Fishing', 11: 'Firemaking',
  12: 'Crafting', 13: 'Smithing', 14: 'Mining', 15: 'Herblore',
  16: 'Agility', 17: 'Thieving', 18: 'Slayer', 19: 'Farming',
  20: 'Runecrafting', 21: 'Hunter', 22: 'Construction', 23: 'Summoning',
  24: 'Dungeoneering', 25: 'Divination', 26: 'Invention', 27: 'Archaeology',
  28: 'Necromancy'
};

// ═══════════════════════════════════════════════════════
// OfficialPlayerDataApi — Singleton
// ═══════════════════════════════════════════════════════

export class OfficialPlayerDataApi {
  private static readonly PROXY_BASE = 'https://multiplayer-globe-pog2.kristain33rs.workers.dev/api/player';
  private static readonly THROTTLE = ApiThrottle.getInstance();

  // ── Runemetrics Profile ────────────────────────────────

  /**
   * Fetch comprehensive player profile data.
   * Now synthesized from Hiscores since Runemetrics is deprecated.
   */
  static async getProfile(playerName: string): Promise<PlayerProfile | null> {
    const hiscores = await this.getHiscores(playerName);
    if (!hiscores) return null;

    const overall = hiscores.get('Overall') || { rank: 0, level: 0, xp: 0 };
    const skills = Array.from(hiscores.entries())
      .filter(([name]) => name !== 'Overall')
      .map(([name, entry]) => ({
        id: Object.entries(SKILL_NAMES).find(([_, n]) => n === name)?.[0] as number || -1,
        name,
        level: entry.level,
        xp: entry.xp,
        rank: entry.rank
      }));

    return {
      name: playerName,
      rank: overall.rank.toString(),
      totalSkill: skills.reduce((sum, s) => sum + s.level, 0),
      totalXp: overall.xp,
      combatLevel: this.calculateCombatLevel(hiscores),
      skills,
      activities: [],
      questsStarted: 0,
      questsComplete: 0,
      questsNotStarted: 0,
      loggedIn: false
    };
  }

  /**
   * Calculate RS3 combat level from hiscores data.
   */
  private static calculateCombatLevel(hiscores: Map<string, HiscoreEntry>): number {
    const attack = hiscores.get('Attack')?.level || 1;
    const strength = hiscores.get('Strength')?.level || 1;
    const defence = hiscores.get('Defence')?.level || 1;
    const constitution = hiscores.get('Constitution')?.level || 10;
    const prayer = hiscores.get('Prayer')?.level || 1;
    const ranged = hiscores.get('Ranged')?.level || 1;
    const magic = hiscores.get('Magic')?.level || 1;
    const necromancy = hiscores.get('Necromancy')?.level || 1;
    const summoning = hiscores.get('Summoning')?.level || 1;

    const base = 0.25 * (defence + constitution + prayer + summoning);
    const melee = 0.325 * (attack + strength);
    const range = 0.325 * (ranged * 2);
    const mage = 0.325 * (magic * 2);
    const necro = 0.325 * (necromancy * 2);
    const highest = Math.max(melee, range, mage, necro);

    return Math.floor(base + highest);
  }

  // ── Hiscores Lite ──────────────────────────────────────

  /**
   * Fetch hiscores in CSV format, parsed to structured data.
   * Returns Map<skillName, HiscoreEntry>.
   */
  static async getHiscores(playerName: string): Promise<Map<string, HiscoreEntry> | null> {
    await this.THROTTLE.acquire('hiscores');

    const url = `${this.PROXY_BASE}/hiscores/lite?player=${encodeURIComponent(playerName)}`;
    logger.debug({ playerName, url }, 'Fetching Hiscores');

    try {
      const res = await fetch(url, {
        headers: { 'Accept': 'text/plain' },
        signal: AbortSignal.timeout(15000)
      });

      if (!res.ok) {
        if (res.status === 429) this.THROTTLE.reportRetryAfter('hiscores', 60);
        return null;
      }

      const csv = await res.text();
      const lines = csv.trim().split('\n');
      const results = new Map<string, HiscoreEntry>();

      if (lines.length === 0) return null;

      // Line 0 is Overall
      const overall = lines[0].split(',').map(v => parseInt(v) || 0);
      results.set('Overall', { rank: overall[0], level: overall[1], xp: overall[2] });

      // Line 1 to 29 are the skills
      for (let i = 1; i < Math.min(30, lines.length); i++) {
        const [rank, level, xp] = lines[i].split(',').map(v => parseInt(v) || 0);
        const skillName = SKILL_NAMES[i - 1];
        if (skillName) {
          results.set(skillName, { rank, level, xp });
        }
      }

      return results;

    } catch (err) {
      logger.error({ playerName, err }, 'Hiscores fetch failed');
      return null;
    }
  }

  // ── Monthly XP ─────────────────────────────────────────

  /**
   * Fetch monthly XP gains for a specific skill.
   */
  static async getMonthlyXp(playerName: string, skillId: number): Promise<MonthlyXpData | null> {
    await this.THROTTLE.acquire('runemetrics');

    const url = `${this.PROXY_BASE}/runemetrics/xp-monthly?searchName=${encodeURIComponent(playerName)}&skillid=${skillId}`;
    try {
      const res = await fetch(url, {
        headers: { 'Accept': 'application/json' },
        signal: AbortSignal.timeout(10000)
      });

      if (!res.ok) return null;
      const data = await res.json();

      return {
        skillId,
        skillName: SKILL_NAMES[skillId] || 'Unknown',
        averageXpGain: data.monthlyXpGain?.averageXpGain || 0,
        totalGain: data.monthlyXpGain?.totalGain || 0,
        totalXp: data.monthlyXpGain?.totalXp || 0,
        monthlyData: (data.monthlyXpGain?.monthData || []).map((m: any) => ({
          month: m.month || '',
          xp: m.xp || 0
        }))
      };

    } catch {
      return null;
    }
  }

  // ── Quest Data ─────────────────────────────────────────

  /**
   * Fetch quest completion status for a player.
   */
  static async getQuests(playerName: string): Promise<QuestData[] | null> {
    await this.THROTTLE.acquire('runemetrics');

    const url = `${this.PROXY_BASE}/runemetrics/quests?user=${encodeURIComponent(playerName)}`;
    try {
      const res = await fetch(url, {
        headers: { 'Accept': 'application/json' },
        signal: AbortSignal.timeout(10000)
      });

      if (!res.ok) return null;
      const data = await res.json();

      return (data.quests || []).map((q: any) => ({
        title: q.title || '',
        status: q.status || 'NOT_STARTED',
        difficulty: q.difficulty || 0,
        members: q.members || false,
        questPoints: q.questPoints || 0,
        userEligible: q.userEligible || false
      }));

    } catch {
      return null;
    }
  }

  // ── High-Level API ─────────────────────────────────────

  /**
   * Full player enrichment: profile + hiscores + quests.
   */
  static async enrichPlayer(playerName: string): Promise<{
    profile: PlayerProfile | null;
    hiscores: Map<string, HiscoreEntry> | null;
    quests: QuestData[] | null;
  }> {
    logger.info({ playerName }, 'Beginning full player enrichment');

    const [profile, hiscores, quests] = await Promise.all([
      this.getProfile(playerName),
      this.getHiscores(playerName),
      this.getQuests(playerName)
    ]);

    return { profile, hiscores, quests };
  }

  /**
   * Verify player can equip an item based on live stats.
   * Used by MechanicalSovereigntyLimb.canEquip().
   */
  static async canEquipItem(
    playerName: string,
    itemId: number,
    requirements: { skill: string; level: number }
  ): Promise<{ canEquip: boolean; currentLevel: number; requiredLevel: number }> {
    const hiscores = await this.getHiscores(playerName);
    if (!hiscores) {
      return { canEquip: false, currentLevel: 0, requiredLevel: requirements.level };
    }

    const entry = hiscores.get(requirements.skill);
    const currentLevel = entry?.level || 1;

    return {
      canEquip: currentLevel >= requirements.level,
      currentLevel,
      requiredLevel: requirements.level
    };
  }
}

/**
 * generate_pedagogy_corpus.ts
 *
 * Sovereignty Grounding Pipeline: Corpus Generation.
 *
 * This script leverages the Unified Enrichment Layer (WikiEquipmentEnricher)
 * to generate a high-fidelity dataset of [VERIFIED] entities.
 *
 * Grounding Sources:
 * 1. RS Wiki (Semantic/Documentation)
 * 2. CacheForensicsLimb (Structural/Official IDs)
 * 3. GeApi (Real-time Market Value)
 * 4. BestiaryApi (Canonical Monster Stats)
 * 5. OfficialPlayerDataApi (Authoritative Player Stats)
 *
 * Target: D:\sovereign\memory\pedagogy\corpus\verified_entities.jsonl
 */

import { WikiEquipmentEnricher } from '../utils/WikiEquipmentEnrich the.js'; // Note: Fix path
import { resolveSovereignPath } from '../utils/SovereignPathResolver.js';
import { writeFileSync, mkdirSync, existsSync } from 'fs';
import { join } from 'path';
import { createLogger } from '../utils/logger.js';

const logger = createLogger('CorpusGenerator');

// ═══════════════════════════════════════════════════════
// Canonical Target Entities
// ═══════════════════════════════════════════════════════

const TARGET_ENTITIES = {
    items: [
        'Abyssal whip',
        'Twisted bow',
        'Tumeken's shadow',
        'Scythe of vitiation',
        'Bandos boots',
        'Slayer helmet',
        'Dragon defender',
        'Skeletal armor',
        'Guthans armor',
        'Ancient staff'
    ],
    monsters: [
        'Vorkath',
        'Zulrah',
        'General Graardor',
        'Bandos General',
        'Nex',
        'Corporeal Beast',
        'Abyssal demon',
        'Chaos elemental',
        'TzKal Wes',
        'Void Knight'
    ],
    players: [
        'Zezima',
        'Pick of Gods',
        ' la- la'
    ]
};

async function generate() {
    logger.info('Starting Pedagogy Corpus Generation...');

    const enricher = WikiEquipmentEnricher.getInstance();
    const corpusPath = resolveSovereignPath('memory/pedagogy/corpus/verified_entities.jsonl');
    const corpusDir = join(corpusPath, '..');

    if (!existsSync(corpusDir)) {
        mkdirSync(corpusDir, { recursive: true });
    }

    const corpus: any[] = [];

    // 1. Enrich Items
    logger.info('Enriching Item Targets...');
    for (const name of TARGET_ENTITIES.items) {
        const data = await enricher.enrichEntity(name);
        if (data) {
            corpus.push({ entity: name, type: 'item', data });
            logger.debug({ name }, 'Item verified');
        }
    }

    // 2. Enrich Monsters
    logger.info('Enriching Monster Targets...');
    for (const name of TARGET_ENTITIES.monsters) {
        const data = await enricher.enrichEntity(name);
        if (data) {
            corpus.push({ entity: name, type: 'monster', data });
            logger.debug({ name }, 'Monster verified');
        }
    }

    // 3. Enrich Players
    logger.info('Enriching Player Targets...');
    for (const name of TARGET_ENTITIES.players) {
        // enrichEntity currently routes to enrichMonster then enrichItem then generic.
        // We need to add a specific player enrichment path or use enrichGeneric.
        const data = await enricher.enrichGeneric(name);
        if (data) {
            corpus.push({ entity: name, type: 'player', data });
            logger.debug({ name }, 'Player verified (generic)');
        }
    }

    // Write to JSONL
    const jsonl = corpus.map(entry => JSON.stringify(entry)).join('\\n') + '\\n';
    writeFileSync(corpusPath, jsonl, 'utf8');

    logger.info({ count: corpus.length, path: corpusPath }, 'Pedagogy Corpus generated successfully.');
}

generate().catch(err => {
    logger.error({ err }, 'Corpus generation failed');
    process.exit(1);
});

import { routePartykitRequest, Server } from "partyserver";

import type { OutgoingMessage, Position } from "../shared";
import type { Connection, ConnectionContext } from "partyserver";

// This is the state that we'll store on each connection
type ConnectionState = {
  position: Position;
};

export class Globe extends Server {
  private nodes: Record<string, any> = {};

  async onStart(): Promise<void> {
    // Load persisted nodes from storage
    this.nodes = (await this.ctx.storage.get<Record<string, any>>("nodes")) || {};
    console.log(`🧠 Globe initialized with ${Object.keys(this.nodes).length} persisted nodes.`);
  }

  onConnect(conn: Connection<ConnectionState>, ctx: ConnectionContext) {
    // Whenever a fresh connection is made, we'll
    // send the entire state to the new connection

    // First, let's extract the position from the Cloudflare headers
    const latitude = ctx.request.cf?.latitude as string | undefined;
    const longitude = ctx.request.cf?.longitude as string | undefined;

    // Phase 19: Allow optional position (system nodes)
    const position = (latitude && longitude) ? {
      lat: parseFloat(latitude),
      lng: parseFloat(longitude),
      id: conn.id,
    } : {
      lat: 0,
      lng: 0,
      id: conn.id,
      system: true
    };

    // And save this on the connection's state
    conn.setState({ position });

    // 🧬 Phase 19: Send durable state-sync to the new connection
    conn.send(JSON.stringify({
      type: "state-sync",
      state: {
        id: "pog2-globe-consensus",
        nodes: this.nodes,
        lastSync: Date.now()
      }
    } satisfies OutgoingMessage));

    // Now, let's send markers to the new connection
    for (const connection of this.getConnections<ConnectionState>()) {
      if (connection.state?.position) {
        conn.send(
          JSON.stringify({
            type: "add-marker",
            position: connection.state.position,
          } satisfies OutgoingMessage),
        );

        // And let's send the new connection's position to all other connections
        if (connection.id !== conn.id) {
          connection.send(
            JSON.stringify({
              type: "add-marker",
              position,
            } satisfies OutgoingMessage),
          );
        }
      }
    }
  }

  // Whenever a connection closes (or errors), we'll broadcast a message to all
  // other connections to remove the marker.
  onCloseOrError(connection: Connection) {
    this.broadcast(
      JSON.stringify({
        type: "remove-marker",
        id: connection.id,
      } satisfies OutgoingMessage),
      [connection.id],
    );
  }

  // Phase 17: Sovereign Bidirectional Tail <-|->
  async onMessage(connection: Connection<ConnectionState>, message: string): Promise<void> {
    try {
      const data = JSON.parse(message);

      // 🧬 Phase 19: Handle Telemetry Persistence (the "State map")
      if (data.type === "update-node") {
        this.nodes[data.nodeId] = data.data;
        // Persist to Durable Object storage
        await this.ctx.storage.put("nodes", this.nodes);

        // Broadcast the update to everyone else
        this.broadcast(message, [connection.id]);
        console.log(`📡 Globe State updated and persisted for node: ${data.nodeId}`);
        return;
      }

      // 1. POG2 -> Globe -> Web Clients (The Outward Tail)
      if (data.type === "direct_perception" || data.type === "entity_spawn") {
        this.broadcast(message, [connection.id]);
        return;
      }

      // 2. Web Clients -> Globe -> POG2 (The Inward Tail)
      if (data.type === "volitional_request") {
        this.broadcast(message, [connection.id]);
        return;
      }
    } catch (err) {
      console.error("Failed to parse Globe message:", err);
    }
  }

  /**
   * 🧬 Phase 20: REST Health & Pulse Endpoints (now handled in main fetch)
   * Kept for backward compatibility with direct DO access
   */
  async onRequest(request: Request): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname.endsWith("/health")) {
      return new Response("OK");
    }
    if (url.pathname.endsWith("/pulse")) {
      return Response.json({
        id: "pog2-globe-consensus",
        nodeCount: Object.keys(this.nodes).length,
        nodes: Object.keys(this.nodes),
        lastSync: Date.now()
      });
    }
    return new Response("Not Found", { status: 404 });
  }

  onClose(connection: Connection): void | Promise<void> {
    this.onCloseOrError(connection);
  }

  onError(connection: Connection): void | Promise<void> {
    this.onCloseOrError(connection);
  }
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    // === Bestiary Proxy Routes ===
    if (url.pathname.startsWith('/api/bestiary/')) {
      const path = url.pathname.replace('/api/bestiary/', '');
      const search = url.search;
      const jagexUrl = `https://secure.runescape.com/m=itemdb_rs/bestiary/${path}${search}`;

      try {
        const res = await fetch(jagexUrl, {
          headers: {
            'User-Agent': 'POG2-Sovereign/1.0 (POG2 Pedagogy Engine; RS3 entity enrichment; admin@pog2.internal; +https://github.com/Kbro1989/POG2)',
            'Accept': 'application/json'
          },
          redirect: 'follow'
        });

        return new Response(res.body, {
          status: res.status,
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Methods': 'GET, OPTIONS',
            'Access-Control-Allow-Headers': 'Content-Type',
            'Cache-Control': 'max-age=3600'
          }
        });
      } catch (err: any) {
        return new Response(JSON.stringify({ error: err.message }), {
          status: 502,
          headers: { 'Content-Type': 'application/json' }
        });
      }
    }

    // === GE Proxy Routes ===
    if (url.pathname.startsWith('/api/ge/')) {
      const path = url.pathname.replace('/api/ge/', '');
      const search = url.search;
      let jagexUrl: string;

      if (path === 'graph.json') {
        const itemId = url.searchParams.get('item');
        jagexUrl = `https://secure.runescape.com/m=itemdb_rs/api/graph/${itemId}.json`;
      } else {
        jagexUrl = `https://secure.runescape.com/m=itemdb_rs/api/catalogue/${path}${search}`;
      }

      try {
        const res = await fetch(jagexUrl, {
          headers: {
            'User-Agent': 'POG2-Sovereign/1.0 (POG2 Pedagogy Engine; RS3 entity enrichment; admin@pog2.internal; +https://github.com/Kbro1989/POG2)',
            'Accept': 'application/json'
          },
          redirect: 'follow'
        });

        return new Response(res.body, {
          status: res.status,
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Methods': 'GET, OPTIONS',
            'Access-Control-Allow-Headers': 'Content-Type',
            'Cache-Control': 'max-age=3600'
          }
        });
      } catch (err: any) {
        return new Response(JSON.stringify({ error: err.message }), {
          status: 502,
          headers: { 'Content-Type': 'application/json' }
        });
      }
    }

    // === Player Data Proxy Routes ===
    if (url.pathname.startsWith('/api/player/')) {
      const path = url.pathname.replace('/api/player/', '');
      const search = url.search;
      let jagexUrl: string;

      if (path === 'runemetrics/profile') {
        const user = url.searchParams.get('user');
        if (!user) return new Response('Missing user parameter', { status: 400 });
        jagexUrl = `https://apps.runescape.com/runemetrics/profile/profile?user=${encodeURIComponent(user)}&activities=20`;
      } else if (path === 'hiscores/lite') {
        const player = url.searchParams.get('player');
        if (!player) return new Response('Missing player parameter', { status: 400 });
        jagexUrl = `https://secure.runescape.com/m=hiscore/index_lite.ws?player=${encodeURIComponent(player)}`;
      } else if (path === 'runemetrics/xp-monthly') {
        const searchName = url.searchParams.get('searchName');
        const skillid = url.searchParams.get('skillid');
        if (!searchName || !skillid) return new Response('Missing searchName or skillid', { status: 400 });
        jagexUrl = `https://apps.runescape.com/runemetrics/xp-monthly?searchName=${encodeURIComponent(searchName)}&skillid=${skillid}`;
      } else if (path === 'runemetrics/quests') {
        const user = url.searchParams.get('user');
        if (!user) return new Response('Missing user parameter', { status: 400 });
        jagexUrl = `https://apps.runescape.com/runemetrics/quests?user=${encodeURIComponent(user)}`;
      } else {
        // Generic player proxy fallback
        jagexUrl = `https://secure.runescape.com/m=hiscore/${path}${search}`;
      }

      try {
        const res = await fetch(jagexUrl, {
          headers: {
            'User-Agent': 'POG2-Sovereign/1.0 (POG2 Pedagogy Engine; RS3 player enrichment; admin@pog2.internal; +https://github.com/Kbro1989/POG2)',
            'Accept': 'application/json'
          },
          redirect: 'follow'
        });

        return new Response(res.body, {
          status: res.status,
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Methods': 'GET, OPTIONS',
            'Access-Control-Allow-Headers': 'Content-Type',
            'Cache-Control': 'max-age=3600'
          }
        });
      } catch (err: any) {
        return new Response(JSON.stringify({ error: err.message }), {
          status: 502,
          headers: { 'Content-Type': 'application/json' }
        });
      }
    }

    // 🧬 Phase 20: Handle health check BEFORE PartyKit routing
    // This fixes the 404 errors seen in Cloudflare logs
    if (url.pathname.endsWith("/health")) {

      return new Response(JSON.stringify({
        status: "healthy",
        timestamp: Date.now(),
        version: "88f9a75e",
        service: "multiplayer-globe-pog2"
      }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    }

    // Route to PartyKit/Durable Object
    return (
      (await routePartykitRequest(request, { ...env })) ||
      new Response("Not Found", { status: 404 })
    );
  },
} satisfies ExportedHandler<Env>;

import { OfficialPlayerDataApi } from './src/utils/OfficialPlayerDataApi.js';

async function test() {
    console.log('--- OfficialPlayerDataApi Verification ---\n');

