        'Tumeken's shadow',
        'Scythe of vitiation',
        'Bandos boots',
        'Slayer helmet',
        'Dragon defender',
        'Skeletal armor',
        'Guthans armor',
        'Ancient staff'
    ],
    monsters: [
        'Vorkath',
