227	    /**
228	     * Fetch raw wikitext for a page. Checks disk cache first.
229	     */
230	    private async fetchWikitext(pageTitle: string): Promise<string | null> {
231	        const cached = this.readCache('wikitext', pageTitle);
232	        if (cached?.wikitext) {
233	            logger.debug({ title: pageTitle }, 'Wikitext served from cache.');
234	            return cached.wikitext;
235	        }
236	
237	        await this.throttle();
238	
239	        const params = new URLSearchParams({
240	            action: 'parse',
241	            format: 'json',
242	            page: pageTitle,
243	            prop: 'wikitext',
244	            origin: '*'
245	        });
246	
247	        try {
248	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
249	                headers: {
250	                    'User-Agent': this.USER_AGENT,
251	                    'Accept': 'application/json'
252	                },
253	                signal: AbortSignal.timeout(10000)
254	            });
255	
256	            if (!response.ok) {
257	                if (response.status === 429) {
258	                    const retryAfter = response.headers.get('Retry-After');
259	                    if (retryAfter) {
