685	    /**
686	     * Detect references to sub-drop-tables in the wikitext.
687	     */
688	    private detectSubTableRefs(wikitext: string): string[] {
689	        const found: string[] = [];
690	        const lowerText = wikitext.toLowerCase();
691	
692	        for (const table of WikiEquipmentEnricher.KNOWN_SUB_TABLES) {
