891	     */
892	    public async enrichMonster(name: string): Promise<WikiPageData> {
893	        const cached = this.readCache('monsters', name);
894	        if (cached && cached.title) {
895	            logger.debug({ name }, 'Monster enrichment served from cache.');
896	            return cached;
897	        }
898	
899	        const monsterMeta = await this.parseMonsterMeta(name);
900	        const dropTables = await this.parseDropTables(name);
901	
902	        // 🧬 Integration: Canonical Bestiary Enrichment
903	        if (monsterMeta) {
904	            const beastId = await BestiaryApi.resolveId(name);
905	            if (beastId) {
906	                const beastData = await BestiaryApi.getBeastData(beastId);
907	                if (beastData) {
908	                    monsterMeta.combatLevel = beastData.level;
909	                    monsterMeta.lifePoints = beastData.lifepoints;
910	                    monsterMeta.weakness = beastData.weakness;
911	                    monsterMeta.slayerLevel = beastData.slayerlevel;
912	                    monsterMeta.slayerCategory = beastData.slayercat;
913	                    monsterMeta.aggressive = beastData.aggressive;
914	                    monsterMeta.poisonous = beastData.poisonous;
915	                    monsterMeta.members = beastData.members;
916	                    logger.debug({ name, id: beastId }, 'Canonical Bestiary data applied to monster meta.');
917	                }
918	            }
919	        }
920	
921	        const wikitext = await this.getWikitextForName(name);
922	        const rawVariables = wikitext
923	            ? (this.extractTemplate(wikitext, 'Infobox Monster') || {})
924	            : {};
925	
926	        const result: WikiPageData = {
927	            title: name,
928	            fetchedAt: Date.now(),
929	            bonuses: null,
930	            itemMeta: null,
931	            monsterMeta,
932	            dropTables,
933	            rawVariables
934	        };
935	
936	        this.writeCache('monsters', name, result);
937	        return result;
938	    }
939	
940	    /**
941	     * Batch enrichment with progress callback.
942	     * Respectfully rate-limited — each API hit spaced by RATE_LIMIT_MS.
943	     */
944	    public async batchEnrich(
945	        names: string[],
946	        type: 'item' | 'monster',
947	        onProgress?: (current: number, total: number, name: string) => void
948	    ): Promise<Map<string, WikiPageData>> {
949	        const results = new Map<string, WikiPageData>();
950	
951	        logger.info({ count: names.length, type }, 'Beginning batch wiki enrichment...');
952	
953	        for (let i = 0; i < names.length; i++) {
954	            const name = names[i];
955	            onProgress?.(i + 1, names.length, name);
956	
957	            try {
958	                const data = type === 'item'
959	                    ? await this.enrichItem(name)
960	                    : await this.enrichMonster(name);
961	                results.set(name, data);
962	            } catch (err) {
963	                logger.warn({ name, err }, 'Batch enrichment failed for entry.');
964	            }
965	        }
966	
967	        logger.info({ completed: results.size, total: names.length }, 'Batch enrichment complete.');
968	        return results;
969	    }
970	
971	    /**
972	     * Unified entry point for entity resolution.
973	     * Uses QueryClassifier to route requests between Structural (Cache) and Semantic (Wiki) paths.
974	     */
975	    public async enrichEntity(query: string): Promise<any> {
976	        const classified = QueryClassifier.classify(query);
977	        logger.info({ query, type: classified.type }, 'Classifying entity query...');
978	
979	        // 1. Route Structural Queries exclusively to CacheForensicsLimb
980	        if (classified.type.startsWith('structural_')) {
981	            const forensics = CacheForensicsLimb.getInstance();
982	            const id = classified.extractedIds[0];
983	
984	            if (classified.type === 'structural_enum') {
985	                return { type: 'enum', data: await forensics.getEnumDetails(id), tag: '[CACHE_VERIFIED]' };
986	            }
987	            if (classified.type === 'structural_id') {
988	                const item = await forensics.getItemDetails(id);
989	                const npc = await forensics.getNpcDetails(id);
990	                return { type: 'id_resolution', item, npc, tag: '[CACHE_VERIFIED]' };
991	            }
992	            return { type: 'structural', data: `Structural query ${classified.type} handled by CacheForensicsLimb`, tag: '[CACHE_EXCLUSIVE]' };
993	        }
994	
995	        // 2. Route Spatial Queries
996	        if (classified.type.startsWith('spatial_')) {
997	            return { type: 'spatial', query: classified.raw, tag: '[SPATIAL_SENSITIVE]' };
998	        }
999	
1000	        // 3. Route Semantic/Hybrid Queries to Wiki + APIs
1001	        const name = classified.extractedNames[0] || query;
1002	
1003	        // Try monster first, then item, then generic
1004	        const monster = await this.enrichMonster(name);
1005	        if (monster.monsterMeta) return { ...monster, tag: '[VERIFIED]' };
1006	
1007	        const item = await this.enrichItem(name);
1008	        if (item.itemMeta) return { ...item, tag: '[VERIFIED]' };
1009	
1010	        return { ...await this.enrichGeneric(name), tag: '[WIKI_ONLY]' };
1011	    }
1012	
