1014	     * Tracks game updates for pedagogy freshness.
1015	     * Parses the Wiki Updates page to flag entities as [POST-UPDATE].
1016	     */
1017	    public async fetchLatestUpdates(): Promise<WikiUpdateMeta[]> {
1018	        logger.info('Fetching latest game updates for temporal grounding...');
1019	        const wikitext = await this.getWikitextForName('Updates');
1020	        if (!wikitext) return [];
1021	
1022	        const updates: WikiUpdateMeta[] = [];
1023	        // This is a simplified parser for the Updates page structure
1024	        const updateBlocks = wikitext.split('==');
