1026	        for (const block of updateBlocks) {
1027	            const dateMatch = block.match(/(\d{1,2}\s\w+ \d{4})/);
1028	            if (!dateMatch) continue;
1029	
1030	            const date = dateMatch[1];
1031	            const titleMatch = block.match(/==\s*([^|]+?)\s*\|/);
1032	            const title = titleMatch ? titleMatch[1].trim() : 'Unknown Update';
1033	
