1038	                url: `https://runescape.wiki/w/Updates#${encodeURIComponent(title)}`,
1039	                isHotfix: block.toLowerCase().includes('hotfix'),
1040	                isColdfix: false,
1041	                affectedEntities: [] // Would require further parsing of the block text for IDs
1042	            });
