1063	            } else if (cls === 'magic') {
1064	                patch.req_magic = bonuses.tier;
1065	            } else if (cls === 'necromancy') {
1066	                patch.req_necromancy = bonuses.tier;
1067	            }
1068	            patch.tier = bonuses.tier;
1069	        }
1070	
1071	        if (bonuses.damage > 0) patch.damage = bonuses.damage;
1072	        if (bonuses.accuracy > 0) patch.accuracy = bonuses.accuracy;
1073	        if (bonuses.armour > 0) patch.armour = bonuses.armour;
1074	        if (bonuses.lifeBonus > 0) patch.lifeBonus = bonuses.lifeBonus;
1075	        if (bonuses.prayerBonus > 0) patch.prayerBonus = bonuses.prayerBonus;
1076	        patch.slot = bonuses.slot;
