421	            const bracePos = lowerText.indexOf('{{', searchIdx);
422	            if (bracePos === -1) break;
423	
424	            let nameStart = bracePos + 2;
425	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
426	
427	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
428	                const afterName = lowerText[nameStart + lowerName.length];
429	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n') {
430	                    // Find closing braces
431	                    let depth = 0;
432	                    let endIdx = bracePos;
433	                    for (let i = bracePos; i < wikitext.length - 1; i++) {
434	                        if (wikitext[i] === '{' && wikitext[i + 1] === '{') { depth++; i++; }
435	                        else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
436	                            depth--; i++;
437	                            if (depth === 0) { endIdx = i + 1; break; }
438	                        }
439	                    }
440	
441	                    const fullContent = wikitext.substring(bracePos + 2, endIdx - 2);
442	                    const pipeIdx = fullContent.indexOf('|');
443	                    if (pipeIdx !== -1) {
444	                        results.push(this.parseTemplateParams(fullContent.substring(pipeIdx + 1)));
445	                    }
446	
447	                    searchIdx = endIdx;
448	                    continue;
449	                }
450	            }
451	            searchIdx = bracePos + 2;
452	        }
453	
454	        return results;
455	    }
