678	    /**
679	     * Detect references to sub-drop-tables in the wikitext.
680	     */
681	    private detectSubTableRefs(wikitext: string): string[] {
682	        const found: string[] = [];
683	        const lowerText = wikitext.toLowerCase();
684	
685	        for (const table of WikiEquipmentEnricher.KNOWN_SUB_TABLES) {
686	            if (lowerText.includes(`{{${table.toLowerCase()}`)) {
687	                found.push(table);
688	            }
689	        }
690	
691	        return found;
692	    }
