694	    /**
695	     * Fetch and parse a sub-drop-table template page.
696	     * These live at Template:{name} on the wiki.
697	     */
698	    private async resolveSubTable(templateName: string): Promise<WikiDropEntry[]> {
699	        // Check cache
700	        const cached = this.readCache('templates', templateName);
701	        if (cached?.entries) {
702	            logger.debug({ templateName }, 'Sub-table served from cache.');
703	            return cached.entries;
704	        }
705	
706	        // Fetch the template page
707	        const wikitext = await this.fetchWikitext(`Template:${templateName}`);
708	        if (!wikitext) return [];
709	
710	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
711	        const entries: WikiDropEntry[] = dropLines.map(dl => ({
712	            itemName: dl['name'] || dl['_1'] || 'Unknown',
713	            quantity: dl['quantity'] || dl['_2'] || '1',
714	            rarity: dl['rarity'] || dl['_3'] || 'Unknown',
715	            isMembers: this.safeBool(dl['members']),
716	            notes: `[${templateName}] ${dl['raritynotes'] || ''}`.trim(),
717	            // Sub-tables (RDT, Gem table) typically have no direct GE price in the template.
718	            // geValue defaults to 0; LootBeamRegistry will use the rarity label (e.g. "Rare drop table") instead.
719	            geValue: this.safeInt(dl['ge'] || dl['value'] || '0')
720	        }));
721	
722	        // Cache the resolved sub-table
723	        this.writeCache('templates', templateName, { entries });
724	        logger.info({ templateName, count: entries.length }, 'Sub-table resolved and cached.');
725	
726	        return entries;
727	    }
