731	    private detectPageType(wikitext: string): 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore' {
732	        const lower = wikitext.toLowerCase();
733	        if (lower.includes('{{infobox monster')) return 'npc';
734	        if (lower.includes('{{infobox item')) return 'item';
735	        if (lower.includes('{{infobox bonuses')) return 'equipment';
736	        if (lower.includes("{{infobox location") || lower.includes("{{infobox area")) return 'place';
737	        if (lower.includes("{{infobox mechanic") || lower.includes("{{infobox gameplay")) return 'mechanic';
738	        return 'lore';
739	    }
