964	    /**
965	     * Unified entry point for entity resolution.
966	     * Uses QueryClassifier to route requests between Structural (Cache) and Semantic (Wiki) paths.
967	     */
968	    public async enrichEntity(query: string): Promise<any> {
969	        const classified = QueryClassifier.classify(query);
970	        logger.info({ query, type: classified.type }, 'Classifying entity query...');
971	
972	        // 1. Route Structural Queries exclusively to CacheForensicsLimb
973	        if (classified.type.startsWith('structural_')) {
974	            const forensics = CacheForensicsLimb.getInstance();
975	            const id = classified.extractedIds[0];
976	
977	            if (classified.type === 'structural_enum') {
978	                return { type: 'enum', data: await forensics.getEnumDetails(id), tag: '[CACHE_VERIFIED]' };
979	            }
980	            if (classified.type === 'structural_id') {
981	                const item = await forensics.getItemDetails(id);
982	                const npc = await forensics.getNpcDetails(id);
983	                return { type: 'id_resolution', item, npc, tag: '[CACHE_VERIFIED]' };
984	            }
985	            return { type: 'structural', data: `Structural query ${classified.type} handled by CacheForensicsLimb`, tag: '[CACHE_EXCLUSIVE]' };
986	        }
987	
988	        // 2. Route Spatial Queries
989	        if (classified.type.startsWith('spatial_')) {
990	            return { type: 'spatial', query: classified.raw, tag: '[SPATIAL_SENSITIVE]' };
991	        }
992	
993	        // 3. Route Semantic/Hybrid Queries to Wiki + APIs
994	        const name = classified.extractedNames[0] || query;
995	
996	        // Try monster first, then item, then generic
997	        const monster = await this.enrichMonster(name);
998	        if (monster.monsterMeta) return { ...monster, tag: '[VERIFIED]' };
999	
1000	        const item = await this.enrichItem(name);
1001	        if (item.itemMeta) return { ...item, tag: '[VERIFIED]' };
1002	
1003	        return { ...await this.enrichGeneric(name), tag: '[WIKI_ONLY]' };
1004	    }
