74	
75	export const SKILL_NAMES: Record<number, string> = {
76	  0: 'Attack', 1: 'Defence', 2: 'Strength', 3: 'Constitution',
77	  4: 'Ranged', 5: 'Prayer', 6: 'Magic', 7: 'Cooking',
78	  8: 'Woodcutting', 9: 'Fletching', 10: 'Fishing', 11: 'Firemaking',
79	  12: 'Crafting', 13: 'Smithing', 14: 'Mining', 15: 'Herblore',
80	  16: 'Agility', 17: 'Thieving', 18: 'Slayer', 19: 'Farming',
81	  20: 'Runecrafting', 21: 'Hunter', 22: 'Construction', 23: 'Summoning',
82	  24: 'Dungeoneering', 25: 'Divination', 26: 'Invention', 27: 'Archaeology',
83	  28: 'Necromancy'
84	};
85	
86	// ═══════════════════════════════════════════════════════
87	// OfficialPlayerDataApi — Singleton
88	// ═══════════════════════════════════════════════════════
89	
90	export class OfficialPlayerDataApi {
91	  private static readonly PROXY_BASE = 'https://multiplayer-globe-pog2.kristain33rs.workers.dev/api/player';
92	  private static readonly THROTTLE = ApiThrottle.getInstance();
93	
94	  // ── Runemetrics Profile ────────────────────────────────
95	
96	  /**
97	   * Fetch comprehensive player profile data.
98	   * Now synthesized from Hiscores since Runemetrics is deprecated.
99	   */
100	  static async getProfile(playerName: string): Promise<PlayerProfile | null> {
101	    const hiscores = await this.getHiscores(playerName);
102	    if (!hiscores) return null;
103	
104	    const overall = hiscores.get('Overall') || { rank: 0, level: 0, xp: 0 };
105	    const skills = Array.from(hiscores.entries())
106	      .filter(([name]) => name !== 'Overall')
107	      .map(([name, entry]) => ({
108	        id: Object.entries(SKILL_NAMES).find(([_, n]) => n === name)?.[0] as number || -1,
109	        name,
110	        level: entry.level,
111	        xp: entry.xp,
112	        rank: entry.rank
113	      }));
114	
115	    return {
116	      name: playerName,
117	      rank: overall.rank.toString(),
118	      totalSkill: skills.reduce((sum, s) => sum + s.level, 0),
119	      totalXp: overall.xp,
120	      combatLevel: this.calculateCombatLevel(hiscores),
121	      skills,
122	      activities: [],
123	      questsStarted: 0,
124	      questsComplete: 0,
125	      questsNotStarted: 0,
126	      loggedIn: false
127	    };
128	  }
129	
130	  /**
131	   * Calculate RS3 combat level from hiscores data.
132	   */
133	  private static calculateCombatLevel(hiscores: Map<string, HiscoreEntry>): number {
134	    const attack = hiscores.get('Attack')?.level || 1;
135	    const strength = hiscores.get('Strength')?.level || 1;
136	    const defence = hiscores.get('Defence')?.level || 1;
137	    const constitution = hiscores.get('Constitution')?.level || 10;
138	    const prayer = hiscores.get('Prayer')?.level || 1;
139	    const ranged = hiscores.get('Ranged')?.level || 1;
140	    const magic = hiscores.get('Magic')?.level || 1;
141	    const necromancy = hiscores.get('Necromancy')?.level || 1;
142	    const summoning = hiscores.get('Summoning')?.level || 1;
143	
144	    const base = 0.25 * (defence + constitution + prayer + summoning);
145	    const melee = 0.325 * (attack + strength);
146	    const range = 0.325 * (ranged * 2);
147	    const mage = 0.325 * (magic * 2);
148	    const necro = 0.325 * (necromancy * 2);
149	    const highest = Math.max(melee, range, mage, necro);
150	
151	    return Math.floor(base + highest);
152	  }
153	
154	  // ── Hiscores Lite ──────────────────────────────────────
155	
156	  /**
157	   * Fetch hiscores in CSV format, parsed to structured data.
158	   * Returns Map<skillName, HiscoreEntry>.
159	   */
160	  static async getHiscores(playerName: string): Promise<Map<string, HiscoreEntry> | null> {
161	    await this.THROTTLE.acquire('hiscores');
162	
163	    const url = `${this.PROXY_BASE}/hiscores/lite?player=${encodeURIComponent(playerName)}`;
164	    logger.debug({ playerName, url }, 'Fetching Hiscores');
