168	        headers: { 'Accept': 'text/plain' },
169	        signal: AbortSignal.timeout(15000)
170	      });
171	
172	      if (!res.ok) {
173	        if (res.status === 429) this.THROTTLE.reportRetryAfter('hiscores', 60);
174	        return null;
175	      }
176	
177	      const csv = await res.text();
178	      const lines = csv.trim().split('\n');
179	      const results = new Map<string, HiscoreEntry>();
180	
181	      if (lines.length === 0) return null;
182	
183	      // Line 0 is Overall
