195	
196	      return results;
197	
198	    } catch (err) {
199	      logger.error({ playerName, err }, 'Hiscores fetch failed');
200	      return null;
201	    }
202	  }
203	
204	  // ── Monthly XP ─────────────────────────────────────────
205	
206	  /**
207	   * Fetch monthly XP gains for a specific skill.
208	   */
209	  static async getMonthlyXp(playerName: string, skillId: number): Promise<MonthlyXpData | null> {
210	    await this.THROTTLE.acquire('runemetrics');
211	
212	    const url = `${this.PROXY_BASE}/runemetrics/xp-monthly?searchName=${encodeURIComponent(playerName)}&skillid=${skillId}`;
213	    try {
214	      const res = await fetch(url, {
