1	/**
2	 * SovereignPathResolver - Centralized TERNARY path resolution
3	 * 
4	 * Philosophy: True Ternary Architecture
5	 * Tier 1 (+1): D:\ Sovereign Drive - Persistent, stable, high capacity
6	 * Tier 2 (0):  ~/.pog2-sovereign - User home, portable across projects
7	 * Tier 3 (-1): .pog in project root - Project-local, fully portable
8	 * 
9	 * The system auto-escalates to the highest available tier, or you can
10	 * force a specific tier via environment variables.
11	 */
12	
13	import { existsSync, mkdirSync, statSync, writeFileSync, readFileSync } from 'fs';
14	import { join, dirname } from 'path';
15	import { homedir } from 'os';
16	
17	// Ternary Path Tiers
18	export const enum PathTier {
19	    Sovereign = 1,   // D:\ drive (most stable)
20	    Home = 0,        // pog2-sovereign
21	    ProjectLocal = -1 // .pog in project root (most portable)
22	}
23	
24	// Core Sovereign Locations (ROOT ANCHORED per user setup)
25	const SOVEREIGN_HOME_ROOT = join(homedir(), '.pog2-sovereign');
26	
27	/**
28	 * Returns the effective Sovereign root directory.
29	 * Priority: 1. Environment Variable POG_SOVEREIGN_ROOT
30	 *           2. Existing D:\sovereign (Backward compatibility)
31	 *           3. OS-aware default (Home directory)
32	 */
33	function getEffectiveSovereignLair(): string {
34	    const envRoot = process.env['POG_SOVEREIGN_ROOT'];
35	    if (envRoot) return envRoot;
36	
37	    // Direct redirection to the Sovereign substrate drive
38	    if (process.platform === 'win32') {
39	        const primaryD = 'D:\\D-sovereign-';
40	        const fallbackD = 'D:\\sovereign';
41	
42	        if (existsSync(primaryD)) return primaryD;
43	        if (existsSync(fallbackD)) return fallbackD;
44	
45	        // If neither exists, attempt to create the primary one
46	        try {
47	            mkdirSync(primaryD, { recursive: true });
48	            return primaryD;
49	        } catch { /* Fallback to home */ }
50	    }
51	
52	    return SOVEREIGN_HOME_ROOT;
53	}
54	
55	const SOVEREIGN_D_LAIR = getEffectiveSovereignLair();
56	const SOVEREIGN_D_ROOT = SOVEREIGN_D_LAIR;
57	
58	// Model Storage (separate from config for size reasons)
59	// DERIVED from SOVEREIGN_D_LAIR to ensure portability
60	const OLLAMA_D_PATH = join(dirname(SOVEREIGN_D_LAIR), 'ollama-models');
61	const GUTENBERG_D_PATH = join(SOVEREIGN_D_LAIR, 'pog-gutenberg');
62	const OLLAMA_LAIR_PATH = join(SOVEREIGN_D_LAIR, 'ollama-models');
63	const GENERATIONS_D_PATH = join(SOVEREIGN_D_LAIR, 'generations');
64	const MEMORY_D_PATH = join(SOVEREIGN_D_LAIR, 'memory');
65	const LEARNING_D_PATH = join(SOVEREIGN_D_LAIR, 'learning');
66	
67	// Cached project root for tier -1 resolution
68	let _projectRoot: string | null = null;
69	
70	/**
71	 * Sets the project root for Tier -1 (ProjectLocal) resolution
72	 */
73	export function setProjectRoot(root: string): void {
74	    _projectRoot = root;
75	}
76	
77	/**
78	 * Detects if a high-performance substrate drive is available.
79	 * Renamed from hasSovereignDrive for universal compatibility.
80	 */
81	export function hasHighPerformanceSubstrate(): boolean {
82	    try {
83	        const root = getEffectiveSovereignLair();
84	        if (!existsSync(root)) return false;
85	        const stat = statSync(root);
86	        return stat.isDirectory();
87	    } catch {
88	        return false;
89	    }
90	}
91	
92	/**
93	 * Legacy alias for hasHighPerformanceSubstrate
94	 */
95	export function hasSovereignDrive(): boolean {
96	    return hasHighPerformanceSubstrate();
97	}
98	
99	/**
100	 * Detects the current path tier based on environment and availability
101	 * @returns PathTier value: 1 (Sovereign), 0 (Home), or -1 (ProjectLocal)
102	 */
103	export function detectPathTier(): PathTier {
104	    // Environment override: force a specific tier
105	    const forcedTier = process.env['POG_PATH_TIER'];
106	    if (forcedTier === '1' || forcedTier === 'sovereign') return PathTier.Sovereign;
107	    if (forcedTier === '0' || forcedTier === 'home') return PathTier.Home;
108	    if (forcedTier === '-1' || forcedTier === 'local') return PathTier.ProjectLocal;
109	
110	    // Auto-detect: try highest tier first
111	    if (hasHighPerformanceSubstrate()) return PathTier.Sovereign;
112	
113	    // Check if project-local is explicitly requested
114	    const useLocal = process.env['POG_USE_LOCAL'] === 'true';
115	    if (useLocal && _projectRoot) return PathTier.ProjectLocal;
116	
117	    // Default to Home tier (balanced) 
118	    return PathTier.Home;
119	}
120	
121	/**
122	 * Ensures the Home tier directory exists and returns its path
123	 */
124	function ensureHomeRoot(): string {
125	    if (!existsSync(SOVEREIGN_HOME_ROOT)) {
126	        mkdirSync(SOVEREIGN_HOME_ROOT, { recursive: true });
127	    }
128	    return SOVEREIGN_HOME_ROOT;
129	}
130	
131	/**
132	 * Returns the root directory for the given (or detected) tier
133	 * True ternary: +1 -> Sovereign Root, 0 -> Home, -1 -> Project-local
134	 */
135	export function getSovereignRoot(tier?: PathTier): string {
