                    results.push({
                        instruction: `Describe cache entity ${npc.id}`,
                        input: JSON.stringify({ id: npc.id, hasWikiPage: false }),
                        output: `[CACHE_ONLY] NPC ${npc.id}. No wiki page. Structural entity only.`,
                        tags: ['[CACHE_ONLY]'],
                        verified: false,
                        cacheId: npc.id,
